// ramakrishna_te.dart
// Ramakrishna Paramhansa quotes and articles (Malyalam)

import '../articlesquotes.dart';

final ramakrishnaSaint = Saint(
  'ramakrishna',
  'Ramakrishna Paramhansa',
  'assets/images/ramkrishna.jpg',
  [
    'ദൈവത്തെ എല്ലാ പാതകളിലൂടെയും അനുഭവിക്കാം. എല്ലാ മതങ്ങളും സത്യമാണ്. പ്രധാനമായത് മേലത്തെ നിലയിൽ എത്തുകയാണ്. നിങ്ങൾക്ക് അത് കല്ലിന്റെ പടികളിലൂടെയോ, മരം പടികളിലൂടെയോ, ബാംബൂ പടികളിലൂടെയോ, അല്ലെങ്കിൽ ഒരു കയറിലൂടെയോ എത്താൻ കഴിയും. നിങ്ങൾ ബാംബൂ കെട്ടിലൂടെയും കയറാൻ കഴിയും.',
    'ഞാൻ ജീവിക്കുന്നതുവരെ, ഞാൻ പഠിക്കുകയാണ്.',
    'കൃപയുടെ കാറ്റുകൾ എപ്പോഴും വീശുന്നു, പക്ഷേ നിങ്ങൾക്ക് കപ്പൽക്കരയുയർത്തേണ്ടതാണ്.',
    'നിങ്ങൾ കിഴക്ക് പോകാൻ ആഗ്രഹിക്കുന്നുവെങ്കിൽ, പടിഞ്ഞാറേയ്ക്ക് പോകരുത്.',
    'ദൈവം എല്ലാ മനുഷ്യരിലും ഉണ്ട്, പക്ഷേ എല്ലാ മനുഷ്യരും ദൈവത്തിൽ ഇല്ല; അതിനാൽ നാം ദു:ഖിക്കുന്നു.',
    'കഥകളിലെ മസ്ക് മൃഗം, അതിന്റെ സ്വന്തം ഗന്ധത്തിന്റെ ഉറവിടം കണ്ടെത്താൻ ലോകമാകെ തിരയുന്നു.',
    'ജ്ഞാനം ഐക്യത്തിലേക്ക് നയിക്കുന്നു, എന്നാൽ അറിവില്ലായ്മ വൈവിധ്യത്തിലേക്ക്.',
    'കൂമ്പിള്ളി ഭൂമിയിലും ജലത്തിലും ജീവിക്കുന്നതുപോലെ, സമ്പൂർണ്ണാത്മാവ് ദൈവത്തിലും ലോകത്തിലും ജീവിക്കുന്നു.',
    'പൂവ് പുഷ്പിക്കുമ്പോൾ, തേൻച്ചില്ലകൾ ക്ഷണിക്കാതെ വരുന്നു.',
    'അദ്ദേഹത്തിന്റെ അനുഗ്രഹത്തിന്റെ കാറ്റ് എപ്പോഴും വീശുന്നു; ആ കാറ്റിനെ പിടിക്കാൻ നിങ്ങളുടെ കപ്പൽ തയാറാക്കുക.',
    'ദൈവത്തിന്റെ അനുഗ്രഹത്തിന്റെ കാറ്റുകൾ എപ്പോഴും വീശുന്നു; നമ്മുടെ帆കൾ ഉയർത്താൻ നമ്മളാണ്.',
    'ഒരു വ്യക്തി അഹങ്കാരം വിട്ടുമാറുന്നതുവരെ ദിവ്യജ്ഞാനം നേടാൻ കഴിയില്ല.',
    'രോഗം ശരീരത്തിനുള്ളത് ആത്മാവ് അടയ്ക്കുന്ന നികുതിയാണ്, വീട്ടുപയോഗത്തിനുള്ള വാടക അടയ്ക്കുന്ന കൂറ്റൻ പോലെ.',
    'എല്ലാ ആഗ്രഹങ്ങളും വിട്ടുവീഴ്ച ചെയ്തവൻ മാത്രമാണ് സത്യമായും സന്തോഷവാനായിരിക്കുന്നത്.',
    'നിങ്ങൾക്ക് നിരവധി കാര്യങ്ങൾ ആഗ്രഹിക്കുകയാണെങ്കിൽ, നിരവധി കാര്യങ്ങൾ കുറച്ചു മാത്രമായി തോന്നും.',
    'ദൈവത്തെ പ്രാർത്ഥിക്കൂ, സമ്പത്ത്, പേര്, സുഖസാധനങ്ങൾ പോലുള്ള താത്കാലിക കാര്യങ്ങളോടുള്ള നിങ്ങളുടെ ആസക്തി ഓരോ ദിവസവും കുറയട്ടെ.',
    'വെള്ളം തേടുന്ന മനുഷ്യന്റെ മുടി തീയിൽ കത്തിയിരിക്കുന്നുവെങ്കിൽ, പ്രകാശം തേടാൻ ശ്രമിക്കരുത്.',
    'ജലവും എണ്ണയും ചേർക്കാൻ കഴിയില്ല. അതുപോലെ, ത്യാഗം കൂടാതെ ആത്മീയ പുരോഗതി സാധ്യമല്ല.',
    'മാഗ്നറ്റിക് നാഡി എപ്പോഴും വടക്കിലേക്ക് സൂചിപ്പിക്കുന്നു, അതിനാൽ തന്നെ നാവിക കപ്പൽ തന്റെ പാത നഷ്ടപ്പെടുന്നില്ല. മനുഷ്യന്റെ ഹൃദയം ദൈവത്തിലേക്കുള്ള ദിശയിൽ തന്നെയുണ്ടെങ്കിൽ, അവൻ ലോകത്തിന്റെ സമുദ്രത്തിൽ നഷ്ടപ്പെടാൻ കഴിയില്ല.',
    'ഒരു കുട്ടിയെപ്പോലെ സരളമാകുന്നതുവരെ, ദിവ്യപ്രകാശം ലഭിക്കുകയില്ല.',
    'അനന്തമായ ജ്ഞാനത്തിലും ആനന്ദത്തിലും ധ്യാനം ചെയ്യുക, അപ്പോൾ നിങ്ങൾക്കും ആനന്ദം ലഭിക്കും.',
    'ദൈവത്തിന്റെ നാമങ്ങൾ അനവധി ആണ്, അവനോടു സമീപിക്കാനുള്ള രൂപങ്ങൾ അശ്രുതമാണ്. നിങ്ങൾ അവനെ ഏത് നാമത്തിലും രൂപത്തിലും ആരാധിക്കുകയാണെങ്കിൽ, അവയിലൂടെ നിങ്ങൾ അവനെ തിരിച്ചറിയും.',
    'ദൈവത്തിന്റെ സാക്ഷാത്കാരം അവനോടുള്ള ഉല്ലാസഭരിതമായ പ്രേമം കൂടാതെ നേടാനാവില്ല.',
    'മഞ്ഞൾക്കൂവലിന്റെ പുഷ്പങ്ങളുടെ പുറത്താണ് തേൻച്ചീന്തി, അതിന്റെ തേൻ രുചിച്ചിട്ടില്ല; അതിനാൽ അത് പുഷ്പത്തിന്റെ ചുറ്റും ഭ്രമിക്കുന്നു, buzzing ശബ്ദം പുറപ്പെടുവിക്കുന്നു; എന്നാൽ അത് പുഷ്പത്തിന്റെ ഉള്ളിൽ പ്രവേശിച്ചാൽ, ശബ്ദമില്ലാതെ നക്ഷത്രം കുടിക്കുന്നു. ഒരു മനുഷ്യൻ തത്വങ്ങൾക്കും dogmas-നും കുറിച്ച് തർക്കിക്കുന്നതുവരെ, അവൻ സത്യമായ വിശ്വാസത്തിന്റെ നക്ഷത്രം രുചിച്ചിട്ടില്ല; അവൻ അതിനെ രുചിച്ചാൽ, അവൻ ശാന്തനും സമാധാനത്തോടെ നിറഞ്ഞവനാകും.',
    'ലോകം ശരിക്കും സത്യവും ഭ്രമവും ചേർന്ന ഒരു സംയോജനം ആണ്. ഭ്രമത്തെ ഉപേക്ഷിച്ച് സത്യത്തെ സ്വീകരിക്കുക.',
    'ദൈവം രണ്ട് അവസരങ്ങളിൽ ചിരിക്കുന്നു. ഒരു രോഗിയുടെ അമ്മയ്ക്ക് ഡോക്ടർ \'ഭയപ്പെടേണ്ട, അമ്മ; ഞാൻ നിശ്ചയമായും നിങ്ങളുടെ കുട്ടിയെ സുഖപ്പെടുത്തും\' എന്ന് പറഞ്ഞപ്പോൾ ദൈവം ചിരിക്കുന്നു, \'ഞാൻ അവന്റെ ജീവൻ എടുക്കാൻ പോകുന്നു, ഈ മനുഷ്യൻ അത് രക്ഷിക്കും എന്ന് പറയുന്നു!\' ഡോക്ടർ തന്റെ കൈയിൽ ശക്തിയുണ്ടെന്ന് കരുതുന്നു, ദൈവം തന്നെ മാസ്റ്റർ ആണെന്ന് മറന്നുകൊണ്ട്. രണ്ട് സഹോദരങ്ങൾ ഒരു നൂലാൽ അവരുടെ ഭൂമി വിഭജിക്കുമ്പോഴും ദൈവം വീണ്ടും ചിരിക്കുന്നു, \'ഈ വശം എന്റെതാണ്, ആ വശം നിന്റെതാണ്\' എന്ന് ഒരുമിച്ച് പറയുന്നു. ദൈവം ചിരിച്ച് പറയുന്നു, \'സമ്പൂർണ്ണ ബ്രഹ്മാണ്ഡം എന്റെതാണ്, പക്ഷേ അവർ ഈ ഭാഗം അല്ലെങ്കിൽ ആ ഭാഗം അവകാശപ്പെടുന്നു.\'',
    'പ്രേമത്തിലൂടെ ഒരാൾ അവനെ കാണുകയും, അവനെ സ്പർശിക്കുകയും, അവനെ അനുഭവിക്കുകയും ചെയ്യാം.',
    'അവിടെ ഒരു വെളിച്ചം കാണുന്നില്ലേ? അത് വിശ്വാസത്തിന്റെ വെളിച്ചമാണ്. അത് ഓരോ മനുഷ്യന്റെ ഹൃദയത്തിലും ജ്വലിക്കുന്നു.',
    'അവൻ വ്യർത്ഥമായി ജനിക്കുന്നു, മനുഷ്യജന്മം നേടുകയും, അത്രയധികം പ്രയാസമുള്ളതും, ഈ ജീവിതത്തിൽ ദൈവത്തെ തിരിച്ചറിയാൻ ശ്രമിക്കാത്തവൻ.',
    'നിങ്ങൾ ആദ്യം സർവശക്തിമാനായ ആത്മാവിന്റെ സത്യമായ ജ്ഞാനത്തോടെ നിങ്ങളുടെ ആത്മാവിനെ ശക്തിപ്പെടുത്തുകയാണെങ്കിൽ, പിന്നെ സമ്പത്ത് കൂടിയുള്ള ലോകത്തിലും ജീവിച്ചാൽ, അവ നിങ്ങൾക്കു എങ്ങനെ ബാധിക്കുകയുമില്ല.',
    'തീരം നദിയുടെ ഭാഗമാണ്, നദി തീരത്തിന്റെ ഭാഗമല്ല. \'ഞാൻ അത്ര പ്രധാനമായ വ്യക്തിയാണ്\' അല്ലെങ്കിൽ \'ഞാൻ ഇങ്ങനെ അല്ലെങ്കിൽ അങ്ങനെ ആണ്\' എന്നതുപോലുള്ള അഹങ്കാരിക ആശയങ്ങൾ ഒഴിവാക്കാതെ ഒരു മനുഷ്യൻ ദൈവത്തെ തിരിച്ചറിയാൻ കഴിയില്ല.',
    'സൂര്യൻ മുഴുവൻ ലോകത്തും ചൂടും വെളിച്ചവും നൽകാൻ കഴിയും, എന്നാൽ മേഘങ്ങൾ തന്റെ കിരണങ്ങളെ മറയ്ക്കുമ്പോൾ അത് ചെയ്യാൻ കഴിയില്ല. അതുപോലെ, അഹങ്കാരം ഹൃദയം മറയ്ക്കുന്നത്ര കാലം, ദൈവം അതിൽ പ്രകാശിക്കാനാവില്ല.',
    'സ്ത്രീയും സ്വർണ്ണവും മാത്രമാണ് ലോകം; അത് മാത്രം മായയാണ്. അതിനാൽ നിങ്ങൾ ദൈവത്തെ കാണുകയോ നേടുകയോ ചെയ്യുന്നില്ല.',
    'സാധാരണ മനുഷ്യർ മതത്തെക്കുറിച്ച് വലിയ വാക്കുകൾ സംസാരിക്കുന്നു, പക്ഷേ അതിന്റെ ഒരു കണവും പ്രായോഗികമായി അനുഷ്ഠിക്കുന്നില്ല. ജ്ഞാനി കുറച്ചുകൂടി സംസാരിക്കുന്നു, എങ്കിലും അദ്ദേഹത്തിന്റെ മുഴുവൻ ജീവിതം പ്രവർത്തനത്തിലൂടെ പ്രകടമായ മതമാണ്.',
    'മുക്തിയുടെ ആത്മാവ് കൈവശമില്ലാത്തവൻ സമാധാനത്തോടെ ജീവിക്കാനാകില്ല.',
    'ഒരു ഗൃഹസ്ഥനായ ജീവിതം നയിക്കുന്ന devotee ദൈവത്തെ വിളിക്കുമ്പോൾ അവൻ സത്യത്തിൽ ഒരു വീരനാണ്. ദൈവം ചിന്തിക്കുന്നു: \'എന്റെ ലോകിക കടമകളുടെ ഇടയിൽ എന്നെ പ്രാർത്ഥിക്കുന്നവൻ സത്യത്തിൽ അനുഗ്രഹിതനാണ്. അവൻ ഒരു വലിയ തടസ്സം മറികടക്കാൻ ശ്രമിക്കുന്നു - ഒരു ടൺ ഭാരം ഉള്ള ഒരു വലിയ കല്ലിനെ തള്ളിക്കളയുന്നതുപോലെ. ഇത്തരത്തിലുള്ള ഒരു മനുഷ്യൻ സത്യമായും ഒരു വീരനാണ്.\'',
    'നിങ്ങൾ ദൈവത്തെ തിരിച്ചറിയാൻ ആഗ്രഹിക്കുന്നുവെങ്കിൽ, നിങ്ങൾക്ക് ശക്തമായ വിരക്തി വളർത്തേണ്ടതുണ്ട്. നിങ്ങളുടെ വഴിയിൽ തടസ്സമാകുന്നതെന്ന് നിങ്ങൾ അനുഭവിക്കുന്നതിനെ ഉടൻ തന്നെ ത്യജിക്കണം. അതിനെ ഭാവിയിൽക്കായി മാറ്റിവയ്ക്കരുത്.',
    'ദൈവത്തെ കണ്ടെത്താനുള്ള വഴി ഭക്തി, ജ്ഞാനം, അല്ലെങ്കിൽ കര്‍മം, നിങ്ങളുടെ അനുയോജ്യമായത് ഏതെങ്കിലും വഴി ആണ്.',
    'ധർമ്മത്തെക്കുറിച്ച് സംസാരിക്കുക എളുപ്പമാണ്, എന്നാൽ അതിനെ പ്രയോഗിക്കുക ബുദ്ധിമുട്ടാണ്.',
    'ബദ്ധത മനസ്സിന്റെതാണ്; സ്വാതന്ത്ര്യവും മനസ്സിന്റെതാണ്. നിങ്ങൾ \'ഞാൻ ഒരു സ്വതന്ത്ര ആത്മാവ്. എന്നെ ബദ്ധപ്പെടുത്താൻ ആരും കഴിയില്ല\' എന്ന് പറയുന്നുവെങ്കിൽ, നിങ്ങൾ സ്വതന്ത്രനാകും.',
    'ബ്രഹ്മൻ എന്താണെന്ന് വിവരിക്കാനാവില്ല. ലോകത്തിലെ എല്ലാ കാര്യങ്ങളും - വേദങ്ങൾ, പുരാണങ്ങൾ, തന്ത്രങ്ങൾ, ആറ് ദർശനങ്ങൾ - നാവിന്റെ സ്പർശം കൊണ്ട് മലിനമായ ഭക്ഷണത്തിന്റെ പോലെ മലിനമായിരിക്കുന്നു, കാരണം അവ നാവിലൂടെ വായിക്കപ്പെട്ടതോ ഉച്ചരിക്കപ്പെട്ടതോ ആണ്. ഈ രീതിയിൽ മലിനമല്ലാത്ത ഒരു മാത്രമാണ്, അത് ബ്രഹ്മൻ ആണ്.',
    'ഒരു മനുഷ്യൻ സത്യത്തിൽ സ്വതന്ത്രനാണ്, ഈ ശരീരിക അവസ്ഥയിൽ പോലും, ദൈവം സത്യമായുള്ള പ്രവർത്തകനാണെന്ന് അവൻ അറിയുന്നെങ്കിൽ, അവൻ ഒരു സാധനമാത്രമാണ്.',
    'പ്രഭുവിന്റെ ഭക്തി അല്ലെങ്കിൽ പ്രണയം കൂടാതെ പ്രവർത്തനം അസഹായമാണ്, അത് ഒറ്റയ്ക്ക് നിലനിൽക്കാൻ കഴിയില്ല.',
    'കാമിനി-കാഞ്ചന (ലോഭവും സ്വർണ്ണവും) യോഗത്തിന് തടസ്സമാണ്.',
    'ഇഷ്ടം അല്ലെങ്കിൽ ആവശ്യങ്ങൾ ഉണ്ടാകുമ്പോൾ, ദു:ഖം ഉണ്ടാകും. ഇഷ്ടം ഇല്ലാത്തപ്പോൾ, നിങ്ങൾ ആത്മനിൽ സ്ഥാപിതമായപ്പോൾ, ആത്മനിൽ മാത്രമേ നിങ്ങളെ സംതൃപ്തിപ്പെടുത്താൻ കഴിയൂ, ആ സമയത്ത് പരിപൂർണ്ണ ആനന്ദം ഉണ്ടാകും.',
    'മനസ്സാണ് ഒരു വ്യക്തിയെ ജ്ഞാനിയാക്കുന്നതും അജ്ഞാനിയാക്കുന്നതും, ബന്ധിതനാക്കുന്നതും മോചിതനാക്കുന്നതും.',
    'ദൈവത്തിനുള്ള സ്നേഹമുള്ളവൻ, ഭാര്യ, കുട്ടികൾ, ബന്ധുക്കൾ, സുഹൃത്തുക്കൾ എന്നിവരോടുള്ള ശാരീരിക ആകർഷണം അനുഭവിക്കുകയില്ല. അവരോടുള്ള കരുണ മാത്രമേ അവൻ നിലനിര്‍ത്തുകയുള്ളൂ.',
    'പ്രേമത്തിന്റെയും സ്നേഹത്തിന്റെയും ആനന്ദങ്ങൾ, ഇന്ദ്രിയങ്ങളുടെ ആനന്ദങ്ങൾ, മറ്റ് എല്ലാ ആസ്വാദ്യങ്ങളും ദൈവത്തിൽ നിന്നുള്ള ആ ആനന്ദത്തിന്റെ പ്രതിഫലമാണ്.',
    'ദൈവത്തെക്കുറിച്ച് സത്യമായ ആഗ്രഹം ഉണ്ടാകുന്നത് മതിയാകും. അവനിലേക്ക് നയിക്കുന്ന വഴികൾ അനന്തമാണ്, വഴികളും അനന്തമാണ്.',
    'ലോകത്തിൽ ഒരു ജലപക്ഷിയുടെ പോലെ ജീവിക്കുക. വെള്ളം പക്ഷിയോട് ചേർന്നു നിൽക്കുന്നു, എന്നാൽ പക്ഷി അതിനെ തള്ളിക്കളയുന്നു. ലോകത്തിൽ ഒരു മണ്ണ് മീനിന്റെ പോലെ ജീവിക്കുക. മീൻ മണ്ണിൽ ജീവിക്കുന്നു, എന്നാൽ അതിന്റെ ത്വക്ക് എപ്പോഴും പ്രകാശമുള്ളതും മിനുക്കിയതുമായിരിക്കുന്നു.',
    'നിങ്ങൾ രാത്രി ആകാശത്തിൽ നിരവധി നക്ഷത്രങ്ങൾ കാണുന്നു, എന്നാൽ സൂര്യൻ ഉയരുമ്പോൾ അവ കാണുന്നില്ല; നിങ്ങൾക്ക് daytime ആകാശത്തിൽ നക്ഷത്രങ്ങൾ ഇല്ല എന്ന് പറയാൻ കഴിയുമോ? അതിനാൽ, മനുഷ്യനേ! നിങ്ങൾ നിങ്ങളുടെ അറിവില്ലായ്മയുടെ ദിവസങ്ങളിൽ ദൈവത്തെ കാണുന്നില്ല എന്നതിനാൽ, ദൈവം ഇല്ല എന്ന് പറയരുത്.',
    'ദൈവത്തിന്റെ അനുഗ്രഹം ഇൻഷുറൻസിനെപ്പോലെയാണ്; നിങ്ങളുടെ ആവശ്യമുള്ള സമയത്ത് അതിന് യാതൊരു പരിധിയും ഇല്ലാതെ നിങ്ങളെ സഹായിക്കും.',
    'എത്ര മതങ്ങൾ, അത്രയും വഴികൾ. ഇത് വെള്ളത്തിന്റെ പോലെ ആണ്, വിവിധ കുപ്പികളിൽ നിന്ന് കുടിക്കാവുന്നുവെങ്കിലും, വെള്ളം ഒരേ തന്നെയാണ്.',
    'ഞാൻ കാണുന്നത് ലോകത്തിനായി, പണത്തിനായി, പേര്, പ്രശസ്തി എന്നിവയ്ക്കായി ആളുകൾ പാഗലായിരിക്കുന്നു; എന്നാൽ ദൈവത്തിനായി ആരും പാഗലായിട്ടില്ല.',
    'ഒരു വ്യക്തിക്ക് സത്യസന്ധമായ ആഗ്രഹം ഉണ്ടെങ്കിൽ, അവൻ തീർച്ചയായും ദൈവത്തെ അനുഭവിക്കും. ഇതിൽ സംശയമില്ല.',
    'മനസ്സ് മണ്ണിൽ മൂടിയ ഒരു സൂചിയുപോലെയാണ്, ദൈവം ഒരു കാന്തിയുപോലെയാണ്. സൂചി മണ്ണിൽ നിന്ന് സ്വതന്ത്രമാകാതെ കാന്തിയുമായി ഐക്യപ്പെടാൻ കഴിയില്ല.',
    'പൂവ് പുഷ്പിക്കുമ്പോൾ, ത beesകൾ ക്ഷണിക്കാതെ വരുന്നു. ഹൃദയം ശുദ്ധമായപ്പോൾ, ദൈവം സ്വയം പ്രത്യക്ഷപ്പെടുന്നു.',
    'ദൈവത്തെ എല്ലാ വഴികളിലൂടെയും, എല്ലാ മതങ്ങളിലൂടെയും അനുഭവിക്കാം. ഒരേ വീട്ടിലേക്ക് എത്താൻ വ്യത്യസ്തമായ മാർഗങ്ങൾ ഉണ്ട്.',
    'എവിടെയും അല്ലെങ്കിൽ അവിടെ എന്ന് അനുഭവപ്പെടുന്ന ദൈവത്തെ ഒരാൾ അനുഭവിച്ചിട്ടില്ലെങ്കിൽ, ദൈവം \'അവിടെ\' ആണെന്ന് തോന്നുന്നു; എന്നാൽ അനുഭവം കഴിഞ്ഞാൽ, ദൈവം ഇവിടെ കൂടാതെ എല്ലായിടത്തും ഉണ്ടെന്ന് കാണുന്നു.',
    'ലോകം വെള്ളം പോലെ ആണ്, മനസ് പാലുപോലെ ആണ്. നിങ്ങൾ വെള്ളത്തിലേക്ക് പാലു ഒഴിച്ചാൽ, അവ ഒരുപോലെ ആകുന്നു. എന്നാൽ നിങ്ങൾ പാലിനെ നെയ്യാക്കി കുഴിച്ചാൽ, അത് വേർപെടുന്നു.',
    'ലോകത്തിൽ ജീവിക്കുമ്പോൾ ഒരാൾ വളരെ ജാഗ്രതയോടെ ഇരിക്കണം. മണ്ണിൽ ജീവിക്കുന്ന ഒരു മണ്ണ് മീനുപോലെ ജീവിക്കുക—അത് മണ്ണിൽ ജീവിച്ചിരുന്നാലും, അതിന്റെ ത്വക്ക് പ്രകാശിതമായിരിക്കും.',
    'ദൈവത്തെ സ്ഥിരമായി ആലോചിക്കുന്ന മനസ്സ് അവനുപോലെയാകും.',
    'ദൈവം നമ്മെ ദു:ഖിപ്പിക്കുന്നത് എന്തുകൊണ്ടാണ്? നമ്മെ സമ്പൂർണ്ണരാക്കാൻ.',
    'മനുഷ്യജീവിതത്തിന്റെ ലക്ഷ്യം ദൈവത്തെ സ്നേഹിക്കുകയാണ്. ഭക്തി ആണ് അതിന്റെ ഒരു അടിസ്ഥാന ഘടകം.',
    'ദൈവം ദൂരത്തിൽ അല്ല. അദ്ദേഹം വളരെ അടുത്താണ്, ഏറ്റവും അടുത്തവനേക്കാൾ അടുത്ത്.',
    'അനേകം പുസ്തകങ്ങൾ വായിച്ചുകൊണ്ട് ആത്മീയ ജ്ഞാനം നേടാനാവില്ല. ആഴത്തിൽ മുങ്ങേണ്ടതാണ്.',
    'ഒരു മനുഷ്യൻ ദിവ്യാനന്ദം അനുഭവിച്ചാൽ, ലോകീയ ആസ്വാദനങ്ങളിൽ അവൻ സന്തോഷം കണ്ടെത്തുന്നില്ല.',
    'കപ്പൽ വെള്ളത്തിൽ ആയിരിക്കാം, എന്നാൽ വെള്ളം കപ്പലിൽ ആകരുത്.',
    'വിശ്വാസം ഉള്ളവന് എല്ലാം ഉണ്ട്; വിശ്വാസം ഇല്ലാത്തവന് എല്ലാം ഇല്ല.',
    'നിങ്ങളുടെ എല്ലാ കടമകളും ചെയ്യുക, പക്ഷേ നിങ്ങളുടെ മനസ്സ് ദൈവത്തിൽ നിക്ഷിപ്തമാക്കുക.',
    'സത്യസന്ധനും ആത്മാർത്ഥനുമായവൻ മാത്രമാണ് വിജയിക്കുന്നത്.',
    'ഫലങ്ങൾ നിറഞ്ഞ മരങ്ങൾ താഴേക്ക് കുനിയുന്നു. സത്യത്തിൽ മഹാന്മാർ എപ്പോഴും വിനീതരാണ്.',
    'ദൈവം മാത്രം പ്രവർത്തകനാണ്; മനുഷ്യൻ വെറും ഒരു ഉപകരണമാണ്.',
    'പ്രാർത്ഥനയാണ് ദൈവത്തിന്റെ ഹൃദയം തുറക്കുന്ന കീ.',
    'ദൈവത്തെ കാണുക ജീവിതത്തിന്റെ ലക്ഷ്യമാണ്. മറ്റെല്ലാം രണ്ടാംതരം ആണ്.',
    'ദൈവത്തോട് നിങ്ങൾ എത്ര അടുത്തുവരുന്നുവോ, അങ്ങനെ നിങ്ങൾ എല്ലാ ജീവികളോടും കൂടുതൽ സ്നേഹം അനുഭവിക്കുന്നു.',
    'ദൈവത്തെ തിരിച്ചറിയാൻ ഒരു കുട്ടിയുടെ വിശ്വാസം വേണം.',
    'മനസ്സു ശുദ്ധമായപ്പോൾ, ദൈവം സ്വാഭാവികമായി തന്റെ സാക്ഷാത്കാരം നടത്തുന്നു.',
    'ലോകം താത്കാലികമാണ്. മാത്രം ദൈവം ശാശ്വതമാണ്.',
    'ദൈവത്തിനായി ഒഴുക്കിയ കണ്ണീർ ഹൃദയത്തിലെ അശുദ്ധികളെ കഴുകുന്നു.',
    'ദൈവം രണ്ടു അവസരങ്ങളിൽ ചിരിക്കുന്നു: വൈദ്യർ ഒരു മനുഷ്യനെ മരുന്നിലൂടെ മാത്രം രക്ഷിക്കാമെന്ന് കരുതുമ്പോഴും, പണ്ഡിതർ ശാസ്ത്രങ്ങളിലൂടെ അവനെ ബന്ധിപ്പിക്കാമെന്ന് കരുതുമ്പോഴും.',
    'ഒരു വ്യക്തി ഉണര്ത്തലിന്റെ ശൂന്യമായ വാദങ്ങളിലൂടെ ദൈവത്തെ തിരിച്ചറിഞ്ഞു കൊണ്ടുവരാൻ കഴിയില്ല. സ്നേഹമാത്രം അവനിലേക്ക് നയിക്കുന്നു.',
    'ദൈവം ആഗ്രഹം ഉള്ളവന്റെ ഹൃദയത്തിൽ സ്വയം പ്രकटിക്കുന്നു.',
    'പൂവിന്റെ പുഷ്പം തുറന്നപ്പോൾ, തേൻച്ചുവട്ടികൾ വരുന്നു. ഹൃദയം പുഷ്പിക്കുമ്പോൾ, ദൈവം പ്രത്യക്ഷപ്പെടുന്നു.',
    'ദൈവം ഒരു മധുരത്തിന്റെ സമുദ്രം പോലെ ആണ്. നിങ്ങൾ എത്രത്തോളം രുചിക്കുകയാണെങ്കിലും, അതിൽ കൂടുതൽ ഉണ്ട്.',
    'ദൈവത്തിന് എല്ലാം സമർപ്പിച്ചവനിൽ ഭയം ഇല്ല.',
    'എന്തിന് ആശങ്കപ്പെടണം? നിങ്ങളെ സൃഷ്ടിച്ചവൻ നിങ്ങളെ പരിചരിക്കും.',
    '\'ഞാൻ\' എന്നും \'എന്റെ\' എന്നും ഉള്ളതുവരെ, അജ്ഞാനം നിലനിൽക്കുന്നു.',
    'ദൈവത്തിന്റെ നാമം ജപിച്ചാൽ മനസ്സ് ശുദ്ധമാകുന്നു.',
    'ഉറച്ച爱的 മുഖാന്തിരം, ഈ കണ്ണുകളാൽ പോലും ദൈവത്തെ കാണാൻ കഴിയും.',
    'ഒരു ഭക്തന് ദൈവം മാത്രമാണ് വേണ്ടത്, മറ്റൊന്നും അല്ല.',
    'ദൈവത്തെ അടുക്കളയിലും കാടിലും തിരിച്ചറിയാം.',
    'ലോകത്തോടുള്ള ബന്ധം ബന്ധിപ്പിക്കുന്നു, ദൈവത്തോടുള്ള ബന്ധം മോചിപ്പിക്കുന്നു.',
    'വിശ്വാസം ഇരുണ്ട മുറിയിലുള്ള ഒരു വിളക്കുപോലെയാണ്.',
    'ഒരു കുട്ടി അമ്മയെക്കൊണ്ട് കരയുന്നത് പോലെ, ദൈവത്തിനായി കരയേണ്ടതാണ്.',
    'ദൈവം രൂപത്തോടും രൂപമില്ലാത്തതോടും കൂടിയാണ്.',
    'നിങ്ങൾ ആത്മീയമായി കൂടുതൽ മുന്നോട്ട് പോകുമ്പോൾ, മറ്റുള്ളവരുടെ ദോഷങ്ങൾ നിങ്ങൾക്ക് കുറവായിരിക്കും കാണാൻ.',
    'എല്ലാം വിട്ടവൻ സത്യത്തിൽ എല്ലാം നേടിയവനാണ്.',
    'ഭക്തിയില്ലാത്ത അറിവ് ഉണക്കവും ശൂന്യവും ആണ്.',
    'ദൈവം ചതുരത്വത്തിലൂടെ ലഭ്യമല്ല, മറിച്ച് സാദ്ധ്യതയിലൂടെ ലഭ്യമാണ്.',
    'ഒരു സമ്പന്നന്റെ വീട്ടിൽ ഒരു സേവികയെപ്പോലെ ലോകത്തിൽ ജീവിക്കണം.',
    'ആഗ്രഹമില്ലാതെ, ഒന്നും നേടാനാവില്ല.',
    'ദൈവം സത്യമായ പ്രാർത്ഥന കേൾക്കുന്നു.',
    'ഈ കാലഘട്ടത്തിൽ ദൈവത്തിന്റെ നാമത്തിന് വലിയ ശക്തിയുണ്ട്.',
    'ദൈവത്തെ നിരന്തരമായി ഓർക്കുന്നതിലൂടെ ഹൃദയം ശുദ്ധമാകുന്നു.',
    'ദൈവത്തെ കണ്ടവൻ അവനെ എല്ലായിടത്തും കാണുന്നു.',
    'ദൈവം തന്റെ സമർപ്പണത്തിന്റെ അനുപാതത്തിൽ തന്നെ സ്വയം വെളിപ്പെടുത്തുന്നു.',
    'മതത്തിന്റെ ആന്തരികത ദൈവത്തിന്റെ പ്രേമമാണ്.',
    'മനസ്സ് ദൈവത്തിൽ ആഴത്തിൽ ലയിച്ചപ്പോൾ, ഇന്ദ്രിയങ്ങൾ അവരുടെ ശക്തി നഷ്ടപ്പെടുന്നു.',
    'ദിവ്യ ആനന്ദം അനുഭവിച്ചവൻ, ലോകീയ സുഖത്തെ രുചിയില്ലാത്തതായി കാണുന്നു.',
    'ദൈവം എല്ലാ ജീവികളുടെയും ആന്തരിക നിയന്ത്രകനാണ്.',
    'വിവിധ നാമങ്ങളിൽ ഒരേ ദൈവത്തെ ആരാധിക്കുന്നു.',
    'ശ്രേഷ്ഠവും ദോഷവും അതിജീവിച്ച് ദൈവത്തെ തിരിച്ചറിയണം.',
    'ഭക്തി ഹൃദയം മൃദുവാക്കുകയും അഹംഭാവം നീക്കുകയും ചെയ്യുന്നു.',
    'ലക്ഷ്യം സംസാരിക്കുക അല്ല, മറിച്ച് അനുഭവിക്കുക ആണ്.',
    'ദൈവം വാദത്തിലൂടെ അല്ല, കണ്ണീർ വഴിയുള്ളവനാണ്.',
    'എന്നെക്കുറിച്ചുള്ള അഹംഭാവം ഇല്ലാതായപ്പോൾ, ദൈവം പ്രകാശിക്കുന്നു.',
    'മനസ്സ് ദൈവത്തിൽ വിശ്രമിക്കുമ്പോൾ ശാന്തമായിരിക്കും.',
    'എല്ലാ ജീവികളിലും ദൈവത്തെ കാണുന്നവൻ ഒരാളെയും വെറുക്കുന്നില്ല.',
    'വിരമിക്കൽ എന്നത് ലോകത്തെ വിട്ടുവിടുക എന്നല്ല, പക്ഷേ ബന്ധം വിട്ടുവിടുക എന്നതാണ്.',
    'ദൈവം മാത്രം സത്യമാണ്; ലോകം അവന്റെ കളിയാണ്.',
    'നിങ്ങൾ ദൈവത്തെ എത്ര കൂടുതൽ സ്നേഹിക്കുന്നു, അത്ര കൂടുതൽ നിങ്ങൾ ലോകീയ കാര്യങ്ങളിൽ താൽപ്പര്യം നഷ്ടപ്പെടുത്തുന്നു.',
    'എല്ലാം ദൈവത്തിന്റെ കാൽക്കൽ സമർപ്പിക്കുക.',
    'വിശ്വാസം ആത്മീയ ജീവിതത്തിന്റെ മൂലമാണ്.',
    'ദൈവത്തെ ഇവിടെയും ഇപ്പോഴും അനുഭവിക്കാം.',
    'ഒരു വ്യക്തി സഹനത്തോടെ ആത്മീയ ശാസ്ത്രം അഭ്യസിക്കണം.',
    'ദൈവത്തിന്റെ അനുഗ്രഹം വിനയമുള്ളവിടങ്ങളിൽ ഉണരുന്നു.',
    'പാത കഠിനമായിരിക്കാം, പക്ഷേ ലക്ഷ്യം മധുരമാണ്.',
    'ദൈവം നിശബ്ദതയുടെ ആഴത്തിൽ അനുഭവപ്പെടുന്നു.',
    'ലോകത്തിൽ ജീവിക്കണം, എന്നാൽ ലോകികമായിരിക്കാതെ.',
    'ദൈവം നിറഞ്ഞ ഹൃദയത്തിൽ ഭയം ഇല്ലാതാകും.',
    'ഭക്തിയാൽ ശുദ്ധീകരിച്ച മനസ് സ്ഥിരമായിരിക്കുന്നു.',
    'ദൈവം ഒരു സ്നേഹഭരിതമായ ഹൃദയത്തിൽ തന്റെ സ്വരൂപം വെളിപ്പെടുത്തുന്നു.',
    'ഹൃദയത്തിന്റെ പരിവർത്തനം ഏറ്റവും വലിയ അത്ഭുതമാണ്.',
    'ദൈവം ശ്വാസത്തിൽ നിന്ന് അടുത്താണ്.',
    'സത്യമായ അറിവ് പ്രണയത്തിലേക്ക് നയിക്കുന്നു.',
    'ദൈവത്തെ സ്നേഹിക്കുന്നവൻ എല്ലാം സ്നേഹിക്കുന്നു.',
    'ദൈവം വാക്കുകൾക്കപ്പുറം ആണെങ്കിലും, ഹൃദയത്തിൽ അനുഭവപ്പെടുന്നു.',
    'ഒരു മുങ്ങുന്ന മനുഷ്യൻ ഒരു തട്ടിൽ പിടിക്കുന്നതുപോലെ, ഒരാൾ ദൈവത്തെ പിടിച്ചിരിക്കുക വേണം.',
    'എല്ലാ ശാസ്ത്രങ്ങളുടെ ആത്മാവ് ഭക്തിയാണ്.',
    'ദൈവം ആഗ്രഹത്തിന്റെ ആത്മാർത്ഥതയ്ക്ക് പ്രതികരിക്കുന്നു.',
    'ആഗ്രഹങ്ങളിൽ നിന്നും മോചിതമായ മനസ്സ് ദിവ്യമായതാകുന്നു.',
    'ദൈവത്തെ സത്യസന്ധമായി അന്വേഷിക്കുന്നവൻ അവനെ തീർച്ചയായും കണ്ടെത്തും.',
    'ദൈവം എല്ലാ ജീവികളുടെയും ആന്തരിക പ്രകാശമാണ്.',
    'ദൈവത്തെ സ്നേഹിക്കുക ഏറ്റവും ഉയർന്ന ജ്ഞാനമാണ്.',
    'ആത്മന് ദൈവത്തിൽ മാത്രമാണ് സമാധാനം കണ്ടെത്തുന്നത്.',
    'ദൈവം ഭക്തന്റെ സുഹൃത്താണ്.',
    'എവിടെ ഭക്തിയുണ്ട്, അവിടെ ദൈവം ഉണ്ട്.',
    'എല്ലാ ആത്മീയ പാതകളുടെയും അവസാനമാണ് ദൈവ സാക്ഷാത്കാരം.',
    'ദൈവത്തെ സത്യമായുള്ള കരച്ചിലോടെ വിളിക്കൂ, അവൻ മറുപടി നൽകേണ്ടതായിരിക്കും.',
  ],
  [
    Article(
        heading: 'മതങ്ങളുടെ സമരസ്യം',
        body: 'രാമകൃഷ്ണന്റെ ജീവിതം എല്ലാ മതങ്ങളുടെ അടിസ്ഥാന ഐക്യത്തിന്റെ ഒരു ജീവിച്ചുള്ള ഉദാഹരണമായിരുന്നു. അദ്ദേഹം വിവിധ ആത്മീയ പാതകൾ പ്രയോഗിച്ചു - ഹിന്ദുമതത്തിന്റെ വിവിധ രൂപങ്ങൾ, ഇസ്ലാം, ക്രിസ്ത്യാനിത്വം - എല്ലാം ഒരേ അന്തിമ സത്യത്തിലേക്ക് നയിക്കുന്നുവെന്ന് അദ്ദേഹം തിരിച്ചറിഞ്ഞു.\n\nഅദ്ദേഹം പലപ്പോഴും വിവിധ പടികൾ ഉപയോഗിച്ച് മേൽക്കൂരയിലേക്ക് എത്തുന്ന കഥ പറയാറുണ്ടായിരുന്നു. ആരെങ്കിലും കല്ലിന്റെ പടികൾ, മരം പടികൾ, ബാംബൂ പടികൾ, അല്ലെങ്കിൽ ഒരു കയറ്റം ഉപയോഗിച്ചാലും, ലക്ഷ്യം ഒരേ - മേൽക്കൂരയിലേക്ക് എത്തുക. അതുപോലെ, എല്ലാ മതങ്ങളും ഒരേ ദിവ്യ ലക്ഷ്യത്തിലേക്ക് നയിക്കുന്ന വ്യത്യസ്ത പാതകളാണ്.\n\nഈ ഉപദേശം അദ്ദേഹത്തിന്റെ കാലത്ത് വിപ്ലവകാരിയായിരുന്നുവും ഇന്നും പ്രസക്തമാണ്. മത വ്യത്യാസങ്ങൾ സമീപനത്തിലെ വ്യത്യാസങ്ങൾ മാത്രമാണ്, സാരത്തിൽ അല്ല. മഹാസത്യമായത് ഒന്ന് മാത്രമാണ്, എങ്കിലും അതിനെ വ്യത്യസ്ത പേരുകളിൽ വിളിക്കുകയും വ്യത്യസ്ത രൂപങ്ങളിൽ ആരാധിക്കുകയും ചെയ്യുന്നു. \\n\\nനമ്മുടെ മതസിദ്ധാന്തങ്ങൾക്കിടയിൽ തർക്കിക്കുന്നത് സത്യമായ വിശ്വാസത്തിന്റെ അമൃതം രുചിച്ചിട്ടില്ല എന്നതിന്റെ സൂചനയാണെന്ന് അദ്ദേഹം ഊന്നിപ്പറഞ്ഞു. ഒരാൾ സത്യത്തിൽ ദൈവത്തെ അനുഭവിക്കുമ്പോൾ, എല്ലാ വാദങ്ങളും അവസാനിക്കുന്നു, ആ വ്യക്തി സമാധാനവും മനസ്സിലാക്കലും കൊണ്ട് നിറഞ്ഞു പോകുന്നു. മതസമരസത്വത്തിന്റെ സന്ദേശം ലോകമാകെയുള്ള കോടിക്കണക്കിന് ആളുകളെ പ്രചോദിപ്പിക്കുകയാണ്, വ്യത്യസ്ത വിശ്വാസങ്ങൾക്കിടയിൽ സഹിഷ്ണുതയും പരസ്പര ആദരവും പ്രോത്സാഹിപ്പിക്കുന്നു.'
    ),
    Article(
        heading: 'ദൈവം അനുഭവിക്കുകയും നിരസിക്കുകയും',
        body: 'രാമകൃഷ്ണൻ പഠിപ്പിച്ചത് മനുഷ്യജീവിതത്തിന്റെ അന്തിമ ലക്ഷ്യം ദൈവസാക്ഷാത്കാരമാണ്. ഈ സാക്ഷാത്കാരം ശക്തമായ ആഗ്രഹവും ത്യാഗവും കൂടാതെ വരില്ലെന്ന് അദ്ദേഹം ഊന്നിപ്പറഞ്ഞു. ഒരു മുങ്ങുന്ന മനുഷ്യൻ വായു ആഗ്രഹിക്കുന്നതുപോലെ, ദൈവത്തെ ആഗ്രഹിക്കണം എന്നും അദ്ദേഹം പലപ്പോഴും പറഞ്ഞു. \n\nത്യാഗം, അദ്ദേഹത്തിന്റെ ഉപദേശത്തിൽ, ലോകത്തെ ഉപേക്ഷിച്ച് സന്ന്യാസി ആകുന്നത് മാത്രമല്ല. മറിച്ച്, സമ്പത്ത്, പ്രശസ്തി, അനുബന്ധങ്ങൾ എന്നിവയോട് ഉള്ള ആസക്തി വിട്ടുമാറുക എന്നതാണ്. ഒരു കാമുകി ഇല വെള്ളത്തിൽ ഒഴുകുമ്പോഴും ഒരിക്കലും ഭജിക്കാത്തതുപോലെ, ആന്തരികമായ അകലം നിലനിര്‍ത്തി ലോകത്ത് ജീവിക്കാം. \n\n"കാമിനി-കഞ്ചന" (ലോഭവും സ്വർണ്ണവും) ആത്മീയ പുരോഗതിക്ക് ഏറ്റവും വലിയ തടസ്സങ്ങളായി അദ്ദേഹം പ്രത്യേകിച്ച് മുന്നറിയിപ്പ് നൽകി. ഇവ sensual pleasures (സംഗമസുഖങ്ങൾ) കൂടാതെ ഭൗതിക സമ്പത്തോടുള്ള ആസക്തിയെ പ്രതിനിധീകരിക്കുന്നു. മനസ്സ് ഇതിൽ കുടുങ്ങിയിരിക്കുന്നതുവരെ, ദൈവത്തെ തിരിച്ചറിഞ്ഞുകൂടിയില്ല. അതേസമയം, രാമകൃഷ്ണൻ ഈ ലോകത്തിലെ കടമകൾ നിർവഹിക്കുമ്പോൾ ആത്മീയമായ ജീവിതം നയിക്കുന്നത് സത്യമായ ഒരു വീരന്റെ പാതയാണെന്ന് അംഗീകരിച്ചു. കുടുംബ ഉത്തരവാദിത്വങ്ങൾ നിറവേറ്റുമ്പോൾ ദൈവത്തെ ഓർക്കുന്ന ഒരു ഗൃഹസ്ഥൻ സ്നേഹിതനാണ്. അത്തരത്തിലുള്ള വ്യക്തി വലിയ തടസ്സങ്ങളെ മറികടക്കുന്നു, ദൈവം അവരുടെ പരിശ്രമങ്ങളെ പ്രത്യേകമായി വിലമതിക്കുന്നു. \n\nദൈവത്തെ തിരിച്ചറിഞ്ഞുകൂടിയതിൽ തടസ്സമായ ഏതെങ്കിലും കാര്യങ്ങളെ ഉടൻ ഉപേക്ഷിച്ച്, ശക്തമായ വിരക്തി വളർത്തുക എന്നതാണ് കീവർ.'
    ),
    Article(
        heading: 'ഗുരുവിന്റെയും ദിവ്യകൃപയുടെയും പങ്ക്',
        body: 'രാമകൃഷ്ണന് ആത്മീയ ജീവിതത്തിലെ ഗുരുവിന്റെ പങ്കിന് വലിയ പ്രാധാന്യം ഉണ്ടായിരുന്നു. അദ്ദേഹം നിരവധി അധ്യാപകരുടെ ശിഷ്യനായിരുന്നു, പിന്നീട് സ്വാമി വിവേകാനന്ദനെ ഉൾപ്പെടെ അനേകം ആളുകളുടെ ഗുരുവായി മാറി. ആത്മീയ പുരോഗതിക്ക് ഒരു സത്യമായ ഗുരു അനിവാര്യമാണ്, കാരണം ഗുരു അജ്ഞാനത്തിന്റെ ഇരുണ്ടത്വം നീക്കുകയും ദൈവത്തിലേക്ക് പോകുന്ന പാത കാണിക്കുകയും ചെയ്യുന്നു. \n\nഎന്നാൽ, ഗുരുവിന്റെ കൃപയും ദൈവത്തിന്റെ കൃപയും ഒടുവിൽ ഒന്നാണ് എന്ന് അദ്ദേഹം ഊന്നിപ്പറഞ്ഞു. ഗുരു മനുഷ്യരൂപത്തിൽ ദിവ്യ കൃപയുടെ പ്രതിഫലനമാണ്, ശിഷ്യനെ അന്തിമ സത്യത്തിലേക്ക് നയിക്കുന്നു. \n\nരാമകൃഷ്ണൻ ദിവ്യ കൃപയെ മനോഹരമായ ഉപമകൾ ഉപയോഗിച്ച് പലപ്പോഴും സംസാരിച്ചിരുന്നു. കൃപയുടെ കാറ്റുകൾ എപ്പോഴും വീശുന്നു, എന്നാൽ അവയെ പിടിക്കാൻ നാം നമ്മുടെ കപ്പലുകൾ ഉയർത്തണം. ദൈവത്തിന്റെ കൃപ എപ്പോഴും ലഭ്യമാണ്, പക്ഷേ അതിനെ സ്വീകരിക്കാൻ നാം ആത്മീയ പ്രാക്ടീസും സത്യസന്ധമായ ആഗ്രഹവും വഴി തയ്യാറാക്കണം. \n\nദൈവത്തിന്റെ കൃപയെ ഇൻഷുറൻസുമായി താരതമ്യം ചെയ്തു, അത് ആവശ്യമുള്ള സമയങ്ങളിൽ അതിരുകൾ ഇല്ലാതെ സഹായിക്കുമെന്ന് അദ്ദേഹം പറഞ്ഞു. സൂര്യന്റെ പ്രകാശം എപ്പോഴും തെളിയുന്നുവെങ്കിലും മേഘങ്ങൾ അത് തടയാൻ കഴിയും, അതുപോലെ ദിവ്യ കൃപ എപ്പോഴും സാന്നിദ്ധ്യമുണ്ട്, പക്ഷേ നമ്മുടെ അഹംകാരംയും അജ്ഞാനവും അതിനെ സ്വീകരിക്കാൻ തടസ്സം സൃഷ്ടിക്കുന്നു. \n\nരാമകൃഷ്ണന്റെ അനുസരിച്ച്, കൃപ സ്വീകരിക്കുന്നതിന്റെ പാത വിനയം, ഭക്തി, ആത്മീയ ശാസ്ത്രങ്ങളുടെ സത്യസന്ധമായ പ്രാക്ടീസിലൂടെ ആണ്. ഭക്തൻ തയ്യാറായപ്പോൾ, കൃപ സ്വാഭാവികമായി ഇറങ്ങുന്നു, ദൈവസാക്ഷാത്കാരത്തിലേക്ക് നയിക്കുന്നു. ദൈവത്തിന്റെ കൃപയുടെ സ്പർശം ഇല്ലാതെ വ്യക്തിഗത പരിശ്രമങ്ങൾ മാത്രം ലക്ഷ്യം നേടാൻ കഴിയില്ല, എന്നാൽ കൃപ സത്യസന്ധമായി അതിനെ തേടുന്നവർക്കു മാത്രമേ വരൂ.'
    ),
    Article(
        heading: 'ആത്മീയ ജ്ഞാനത്തോടെ ലോകത്തിൽ ജീവിക്കുക',
        body: 'രാമകൃഷ്ണന്റെ ഏറ്റവും പ്രായോഗികമായ ഉപദേശങ്ങളിൽ ഒന്നാണ് ലോകീയ ജീവിതത്തിൽ ഏർപ്പെടുമ്പോൾ ആത്മീയമായി എങ്ങനെ ജീവിക്കണമെന്ന്. ലോകം വിട്ടുപോകുകയും സന്ന്യാസി ആകുകയും ചെയ്യാൻ എല്ലാവർക്കും കഴിയില്ല എന്ന് അദ്ദേഹം തിരിച്ചറിഞ്ഞു, എന്നാൽ ആത്മീയ ജീവിതം സന്ന്യാസികൾക്കു മാത്രം പരിമിതമായിരിക്കരുത്.\n\nലോകത്തിൽ ജീവിക്കുമ്പോൾ അതിൽ നിന്ന് മലിനമാകാതെ എങ്ങനെ ജീവിക്കാമെന്ന് അദ്ദേഹം നിരവധി മനോഹരമായ ഉദാഹരണങ്ങൾ നൽകി. വെള്ളത്തിൽ ജീവിക്കുന്ന പക്ഷി, എന്നാൽ അതിന്റെ തൊലികൾ ഉണക്കമായിരിക്കുമ്പോൾ, അല്ലെങ്കിൽ മണ്ണിൽ ജീവിക്കുന്ന മണ്ണ് മത്സ്യം, എന്നാൽ അതിന്റെ ത്വക്ക് പ്രകാശമുള്ളതും മിനുക്കിയതും ആയിരിക്കുമ്പോൾ, ആത്മീയ ആഗ്രഹിക്കുന്നവൻ ലോകത്തിൽ ജീവിക്കുമ്പോൾ ആന്തരികമായി ശുദ്ധമായിരിക്കണം.\n\nരാമകൃഷ്ണൻ പഠിപ്പിച്ചത്, ഒരാൾ ആദ്യം സർവജ്ഞാത്വത്തിന്റെ സത്യമായ അറിവോടെ സ്വന്തം ആത്മാവിനെ ശക്തിപ്പെടുത്തിയാൽ, സമ്പത്തിലും ലോകീയതയിലും ജീവിക്കുന്നത് negatively ബാധിക്കില്ല. ആത്മീയ ബോധത്തിൽ ഉറച്ചുനിൽക്കുന്നത് ലോകത്തോടുള്ള മുഴുവൻ ഇടപെടലുകൾക്ക് മുമ്പ് പ്രധാനമാണ്. വീട്ടുകാർക്കും ആത്മീയ പ്രാക്ടീസ് നടത്തുന്നത് എത്രമാത്രം പ്രധാനമാണെന്ന് അദ്ദേഹം ഊന്നിപ്പറഞ്ഞു. പ്രാർത്ഥന, ധ്യാനം, ചിന്തനം എന്നിവയ്ക്കായി ഓരോ ദിവസവും സമയം മാറ്റിവയ്ക്കുന്നത് അനിവാര്യമാണ്. ആരാധനയ്ക്കായി വീട്ടിൽ ഒരു സ്ഥലം സൃഷ്ടിക്കാൻ ആളുകളെ അദ്ദേഹം ഉപദേശിച്ചു, കൂടാതെ ദിവസേന ആത്മീയ ശാസനകൾ പാലിക്കേണ്ടതിന്റെ ആവശ്യകതയും പറഞ്ഞു.\n\nരാമകൃഷ്ണൻ മറ്റൊരു പ്രധാനമായ പാഠം നൽകുന്നു: ശരിയായ മനോഭാവത്തിൽ മറ്റുള്ളവർക്കുള്ള സേവനം, ദൈവത്തിന്‍റെ സേവനമാണ്. എല്ലാ ജീവികളിലും ദൈവത്തെ കാണുകയും, അവരെ സ്നേഹവും കരുണയും കൊണ്ട് സേവിക്കുകയും ചെയ്യുന്നത് ശക്തമായ ആത്മീയ പ്രാക്ടീസാണ്. അവൻ തന്റെ ജീവിതത്തിലൂടെ കാണിച്ചത്, എല്ലാ ജീവിതശ്രേണികളിൽ നിന്നുള്ള ആളുകളുമായി ഇടപെടുമ്പോഴും, ഏറ്റവും ഉയർന്ന ആത്മീയ ബോധം നിലനിര്‍ത്താൻ കഴിയുന്നതാണ്. \n\nഅവന്റെ സന്ദേശം വ്യക്തമായിരുന്നു: ആത്മീയ ജീവിതം ദൈനംദിന ജീവിതത്തിൽ നിന്നു വേർപെടുത്തപ്പെട്ടിട്ടില്ല. ഓരോ പ്രവർത്തനവും ദിവ്യത്തെക്കുറിച്ചുള്ള ബോധത്തോടെ ചെയ്യുമ്പോൾ, ഓരോ വ്യക്തിയെയും ദൈവത്തിന്റെ പ്രതിഫലനമായി കാണുമ്പോൾ, ആ മുഴുവൻ ജീവിതവും ഒരു ആത്മീയ അഭ്യാസമാകുന്നു. ഈ പ്രായോഗിക സമീപനം ആത്മീയതയിലേക്കുള്ള അവന്റെ പഠനങ്ങളെ സാധാരണ ജീവിതം നയിക്കുന്ന കോടിക്കണക്കിന് ആളുകൾക്ക് പ്രാപ്യവും പ്രസക്തവുമായതാക്കി.'
    ),
  ],
);
